import java.io.*;

public class Main {
    public static void main(String[] args) {
        try {
            InputStreamReader in = new InputStreamReader(System.in);
            PrintWriter out = new PrintWriter(System.out);
            int first = in.read();
            if (first == -1) {
                throw new NullPointerException();
            }
            if (first == '\n' || first == '\r') {
                out.println(0);
                out.close();
                return;
            }
            int previous = first;
            int runLength = 1;
            int result = 0;
            while (true) {
                int c = in.read();
                if (c == -1 || c == '\n' || c == '\r') {
                    if ((runLength & 1) == 0) {
                        result++;
                    }
                    break;
                }
                if (c == previous) {
                    runLength++;
                } else {
                    if ((runLength & 1) == 0) {
                        result++;
                    }
                    previous = c;
                    runLength = 1;
                }
            }
            out.println(result);
            out.close();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}
